=== GET /v1/instances
kind: route
group: Instances
src: api/src/external_api/instance_endpoints.rs :: #[endpoint { method = GET, path = "/v1/instances",
doc: Lists the instances of a project, sorted by name.
---
route GET /v1/instances(project):
    #> Find who is calling -> session_auth.authenticate | 401
    caller = session_auth.authenticate(request)
    #> List the project's instances -> instances.list_instances | 404 ProjectNotFound
    return instances.list_instances(caller, project)

=== POST /v1/instances
kind: route
group: Instances
src: api/src/external_api/instance_endpoints.rs :: #[endpoint { method = POST, path = "/v1/instances",
doc: Creates an instance in a project, with a boot disk and an address. It answers at once with the instance as "creating". The console then asks for the instance again until it is running or failed.
---
route POST /v1/instances(
        project, name, ncpus, memory_gib, boot_disk_size_gib):
    #> Find who is calling -> session_auth.authenticate | 401
    caller = session_auth.authenticate(request)
    #> Create the instance -> instances.create_instance | 400 | 403 | 404 | 409 | 503
    instance = instances.create_instance(caller, project,
        {name, ncpus, memory_gib, boot_disk_size_gib})
    return 201, instance

=== GET /v1/instances/{instance}
kind: route
group: Instances
src: api/src/external_api/instance_endpoints.rs :: #[endpoint { method = GET, path = "/v1/instances/{instance}",
doc: Shows one instance as it is now. The console calls this every second while an instance is changing state.
---
route GET /v1/instances/{instance}(instance):
    #> Find who is calling -> session_auth.authenticate | 401
    caller = session_auth.authenticate(request)
    #> Load the instance -> instances.view_instance | 404 InstanceNotFound
    return instances.view_instance(caller, instance)

